CONFIG_REL = "projects/sci-assistant/config/sci_assistant_config.yaml"

# ---------------------------------------------------------------- 词表
SYNTH_PAT = [
    "合成", "制备", "水热", "煅烧", "电沉积", "球磨", "溶胶", "热解", "旋涂",
    "共沉淀", "固相法", "退火", "磁控溅射",
]
CHAR_RE = [re.compile(p, re.I) for p in [
    r"\bSEM\b", r"\bTEM\b", r"\bXRD\b", r"\bXPS\b", r"\bEIS\b", r"\bNMR\b",
    r"Raman", r"\bFTIR\b", r"\bXANES\b", r"\bEXAFS\b", r"\bAFM\b", r"\bBET\b",
    r"\bDSC\b", r"\bTGA\b", r"\bCV\b", r"\bLSV\b", r"\bGCD\b", r"\bDEMS\b",
]]
# 「未做合成 / 无制备步骤」这类否定句里的「合成/制备」不算有合成段
NEG_SYNTH_RE = re.compile(r"(?:未|无|没有|不涉及|未涉及|无需|不做)[^。；;\n]{0,8}?(?:合成|制备)")

# 标记必须带冒号才算「标准 callout」：库里存在限定式写法，
# 如「⚠️ 无实验验证（就 ML 闭环而言）」——那是**限定范围**的标记，不是整篇无实验。
# 实测 67 张含「无实验验证」的卡里只有 41 张是带冒号的标准 callout。
MK_COMP = re.compile(r"无实验验证\s*[:：]")
MK_SELF = re.compile(r"自报数字\s*[:：]")
MK_SINGLE = re.compile(r"单源论断\s*[:：]")

CARD_SIGNALS = ("comp-no-expt", "synth-no-char", "single-lab-claim")
EXTRA_CARD_SIGNALS = ("method-orphan",)   # N3：方法孤证（需 methods_db）
SUB_SIGNALS = ("cross-domain-gap",)        # N3：跨域未迁移（子方向级）
SIGNAL_DESC = {
    "comp-no-expt": "正文标注『无实验验证』（纯计算/模拟结论，无合成或表征佐证）——实验验证是可切入的空白",
    "synth-no-char": "有合成工艺但正文只提到 1 种表征手段——系统表征是可切入的空白",
    "single-lab-claim": "同时标注『自报数字』与『单源论断』（关键性能仅本组自报）——独立验证是可切入的空白",
    "temporal-gap": "该子方向近期文献骤减但其概念页证据仍强——可能被遗忘的有价值方向",
    "method-orphan": "本方向只有 1 篇支撑、邻域却有 ≥2 篇验证的方法——方法学证据薄，需重复或标准化",
    "cross-domain-gap": "该技术在相邻子方向已被多张卡采用、本方向却未系统使用——跨域迁移是可切入的空白",
}
# 跨域信号用的技术词表（与 sci_method_extract 的 TECHNIQUES 保持同源口径）
TECH_TERMS = ["SEM", "TEM", "XRD", "XPS", "EIS", "NMR", "Raman", "FTIR", "XANES",
              "EXAFS", "AFM", "BET", "DSC", "TGA", "CV", "LSV", "GCD", "DEMS",
              "GITT", "EBSD", "PXRD", "Mössbauer", "ICP", "XRF", "SIMS", "STEM",
              "SAED", "DRT", "XAS", "PDF"]
OPPORTUNITY_HIGH = 0.5
OPPORTUNITY_MED = 0.25


# ---------------------------------------------------------------- 配置 / 输入

def load_config(path=None):
    import yaml
    p = path or os.path.join(K.VAULT, CONFIG_REL)
    with open(p, "r", encoding="utf-8") as f:
        return yaml.safe_load(f) or {}


def landscape_path(topic):
    """--topic 可给名字（找 topics/<slug>/landscape.json）或直接给 json 路径。"""
    if topic.endswith(".json") and os.path.isfile(topic):
        return os.path.abspath(topic)
    base = os.path.join(K.VAULT, "projects/sci-assistant/topics", topic)
    p = os.path.join(base, "landscape.json")
    if not os.path.isfile(p):
        raise SystemExit(f"[!] 找不到 {p}；先跑 python tools/sci_landscape.py --direction \"{topic}\" --cluster")
    return p


def load_landscape(path):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


def load_evidence_bases():
    p = os.path.join(K.INDEX_DIR, "meta_fm.json")
    if not os.path.isfile(p):
        return {}
    with open(p, encoding="utf-8") as f:
        fm = (json.load(f).get("page_fm") or {})
    return {k: (v or {}).get("evidence_base") for k, v in fm.items()}


# ---------------------------------------------------------------- 单卡信号

def detect_card_signals(body):
    """返回 (signal_set, detail)。纯函数，自检直接喂文本。"""
    body_kw = NEG_SYNTH_RE.sub("", body)      # 先剔除「未做合成/无制备步骤」这类否定句
    has_synth = any(k in body_kw for k in SYNTH_PAT)
    n_char = sum(1 for r in CHAR_RE if r.search(body))
    review = ("体裁提示" in body) or ("综述" in body[:800])
    sig = set()
    # 只用**标准 callout（带冒号）**的人工标记判纯计算：限定式写法（「无实验验证（就 ML
    # 闭环而言）」）指的是某个子链条，不是整篇无实验。
    if MK_COMP.search(body):
        sig.add("comp-no-expt")
    # 有合成段、但正文只提到 1 种表征手段；0 种的通常是计算/提及式文章，不报；
    # 已标"无实验验证"的卡也不报——否则同一张卡会同时被判「没做实验」和「做了但没表征」。
    if (has_synth and n_char == 1 and not review
            and not MK_COMP.search(body)):
        sig.add("synth-no-char")
    # 两个（带冒号的）标记同时出现才算"单实验室自报"
    if MK_SELF.search(body) and MK_SINGLE.search(body):
        sig.add("single-lab-claim")
    return sig, {"has_synth": has_synth, "n_char": n_char, "review": review}


def load_method_map(cfg=None):
    """从 methods_db 建 card → 方法键、方法键 → 卡片 的索引（N3 方法孤证用）。"""
    rel = ((cfg or {}).get("sci") or {}).get("methods_db") or \
        "projects/sci-assistant/knowledge/methods_db.json"
    p = rel if os.path.isabs(rel) else os.path.join(K.VAULT, rel)
    if not os.path.isfile(p):
        return None
    methods = json.load(open(p, encoding="utf-8")).get("methods") or []
    per_card, key_cards = {}, {}
    for m in methods:
        card = os.path.basename(m.get("page_path") or "").replace(".md", "")
        if not card:
            continue
        key = f"{m.get('name_zh')}|{m.get('category')}"
        per_card.setdefault(card, set()).add(key)
        key_cards.setdefault(key, set()).add(card)
    return {"per_card": per_card, "key_cards": key_cards}


def method_flags(card, method_map):
    """(是否有方法记录, 是否全是孤证)。没有 methods_db 时返回 (False, False)。"""
    if not method_map:
        return False, False
    keys = method_map["per_card"].get(card) or set()
    if not keys:
        return False, False
    return True, all(len(method_map["key_cards"].get(k, set())) <= 1 for k in keys)


def read_cards(cands, method_map=None):
    """name -> {signals, year, score, review, path, missing, techniques, has_record}。"""
    cards = {}
    for c in cands:
        name = c["name"]
        path = c.get("path") or os.path.join("wiki/sources", name + ".md")
        full = os.path.join(K.VAULT, path)
        rec = {"year": str(c.get("year") or ""), "score": float(c.get("score") or 0.0),
               "path": path, "signals": set(), "review": False, "missing": False,
               "techniques": [], "has_record": False}
        if not os.path.isfile(full):
            rec["missing"] = True
            cards[name] = rec
            continue
        body = K.read_text(full)
        sig, detail = detect_card_signals(body)
        rec["signals"] = sig
        rec["review"] = detail["review"]
        rec["detail"] = detail
        rec["techniques"] = [t for t in TECH_TERMS if t in body]
        rec["has_record"] = bool(method_map and method_map["per_card"].get(name))
        cards[name] = rec
    return cards


def baselines(cards):
    """每个卡级信号在**非综述**候选卡上的命中率。

    综述/评述是二手转述，其「自报数字」「无实验验证」不代表作者自己的研究，
    计入分母会把基线抬高、把真实缺口稀释掉（实测 comp-no-expt 基线曾因此偏高）。
    """
    usable = [c for c in cards.values()
              if not c.get("missing") and not c.get("review")]
    out = {}
    for sig in CARD_SIGNALS:
        if not usable:
            out[sig] = 0.0
            continue
        out[sig] = round(sum(1 for c in usable if sig in c["signals"]) / len(usable), 4)
    return out


# ---------------------------------------------------------------- 方法证据薄（N3）

def build_method_usage(cards, subs, method_map):
    """方法键 → {子方向: 卡片数}；只数非综述、非缺失、有方法记录的卡。"""
    usage = {}
    if not method_map:
        return usage
    for sub in subs:
        sname = sub.get("name")
        for m in sub.get("members") or []:
            c = cards.get(m)
            if not c or c.get("missing") or c.get("review"):
                continue
            for key in (method_map["per_card"].get(m) or set()):
                usage.setdefault(key, {}).setdefault(sname, 0)
                usage[key][sname] += 1
    return usage


def thin_methods_for(name, usage, min_other=2):
    """本方向仅 1 张卡、别的子方向合计 ≥min_other 张卡的方法键。返回 (thin, used)。"""
    thin, used = [], []
    for key, d in usage.items():
        if d.get(name, 0) >= 1:
            used.append(key)
        if d.get(name, 0) == 1 and sum(n for s, n in d.items() if s != name) >= min_other:
            thin.append(key)
    return thin, used


def _key_refs(thin, name, subs, cards, method_map, limit=5):
    out, seen = [], set()
    for sub in subs:
        if sub.get("name") != name:
            continue
        for m in sub.get("members") or []:
            if m in seen or not cards.get(m):
                continue
            keys = method_map["per_card"].get(m) or set()
            hit = [k for k in thin if k in keys]
            if hit:
                seen.add(m)
                out.append({"name": m, "citation": f"[[sources/{m}]]",
                            "year": cards[m].get("year"), "method": hit[0].split("|")[0]})
                if len(out) >= limit:
                    return out
    return out


# ---------------------------------------------------------------- 跨域信号（N3）

def build_tech_usage(cards, subs):
    """技术词 → {子方向: 卡片数}（只数非综述、非缺失的一手卡）。"""
    usage = {}
    for sub in subs:
        name = sub.get("name")
        for m in sub.get("members") or []:
            c = cards.get(m)
            if not c or c.get("missing") or c.get("review"):
                continue
            for t in c.get("techniques") or []:
                usage.setdefault(t, {}).setdefault(name, 0)
                usage[t][name] += 1
    return usage


def cross_domain_for(name, cards, subs, usage, min_else=3, min_subs=2):
    """返回 (候选技术, 邻域成熟技术)。成熟 = 在 ≥min_subs 个**别的**子方向各 ≥min_else 张卡。"""
    mature = {t for t, d in usage.items()
              if sum(1 for s, n in d.items() if s != name and n >= min_else) >= min_subs}
    used = {t for t, d in usage.items() if d.get(name, 0) >= 1}
    cand = sorted(mature - used,
                  key=lambda t: -sum(n for s, n in usage[t].items() if s != name))
    return cand, sorted(mature)


def _tech_refs(cands, name, subs, cards, limit=5):
    seen, out = set(), []
    for t in cands:
        for sub in subs:
            if sub.get("name") == name:
                continue
            for m in sub.get("members") or []:
                c = cards.get(m)
                if not c or m in seen:
                    continue
                if t in (c.get("techniques") or []):
                    seen.add(m)
                    out.append({"name": m, "citation": f"[[sources/{m}]]",
                                "year": c.get("year"), "technique": t})
                    if len(out) >= limit:
                        return out
    return out


def _opportunity(score, high=None, med=None):
    high = OPPORTUNITY_HIGH if high is None else high
    med = OPPORTUNITY_MED if med is None else med
    if score >= high:
        return "high"
    if score >= med:
        return "medium"
    return "low"


def _refs(members, cards, limit=5):
    ranked = sorted(members, key=lambda m: -float(cards[m].get("score") or 0.0))
    return [{"name": m, "citation": f"[[sources/{m}]]",
             "year": cards[m].get("year")} for m in ranked[:limit]]


def aggregate_gaps(cards, subs, base_rates, evidence_bases, weights,
                   min_hits=2, min_lift=0.1, opp_high=None, opp_med=None,
                   tech_usage=None, method_usage=None, method_map=None,
                   cd_min_cards=3, cd_min_subs=2, orphan_min_other=2):
    """纯函数：按子方向聚合信号，用 lift 判缺口。返回 (gaps, summary)。"""
    gaps = []
    cd, cd_base = {}, 0.0
    if tech_usage:
        for sub in subs:
            cand, mature = cross_domain_for(sub.get("name"), cards, subs, tech_usage,
                                            min_else=cd_min_cards, min_subs=cd_min_subs)
            if mature:
                cd[sub.get("name")] = (cand, mature)
        if cd:
            cd_base = round(sum(len(c) / len(m) for c, m in cd.values()) / len(cd), 4)
    thin_stats, thin_base = {}, 0.0
    if method_usage:
        for sub in subs:
            thin, used = thin_methods_for(sub.get("name"), method_usage,
                                          min_other=orphan_min_other)
            if used:
                thin_stats[sub.get("name")] = (thin, len(used))
        if thin_stats:
            thin_base = round(sum(len(t) / n for t, n in thin_stats.values())
                              / len(thin_stats), 4)
    for sub in subs:
        members_all = [m for m in (sub.get("members") or [])
                       if m in cards and not cards[m].get("missing")]
        # 卡级信号只看一手研究：综述/评述不计（其「自报数字」「制备」都是转述）
        members = [m for m in members_all if not cards[m]["review"]]
        if not members:
            continue
        n = len(members)
        for sig in CARD_SIGNALS:
            n_sig = n
            hits = [m for m in members if sig in cards[m]["signals"]]
            if n_sig < 3 or len(hits) < min_hits:
                continue
            rate = len(hits) / n_sig
            base = float(base_rates.get(sig, 0.0))
            lift = round(rate - base, 3)      # 先定下对外口径，score 用它算，保证可复算
            if lift < min_lift:
                continue
            score = round(float(weights.get(sig, 1.0)) * lift
                          * (len(hits) / (len(hits) + 3.0)), 3)
            gaps.append({
                "sub_direction": sub.get("name"),
                "signal": sig,
                "hits": len(hits),
                "eligible": n_sig,
                "rate": round(rate, 3),
                "baseline": base,
                "lift": round(lift, 3),
                "score": score,
                "opportunity": _opportunity(score, opp_high, opp_med),
                "reason": (f"{sub.get('name')} 中 {len(hits)}/{n_sig} 篇（{rate:.0%}）"
                           f"命中「{sig}」，高于全方向基线 {base:.0%}"
                           f"（lift {lift:+.0%}）；{SIGNAL_DESC[sig]}"),
                "evidence_refs": _refs(hits, cards),
            })
        # 时间空白（子方向级，含综述：年份是事实）
        years = [int(cards[m]["year"]) for m in members_all
                 if str(cards[m].get("year", "")).isdigit()]
        eb = evidence_bases.get(sub.get("name"))
        if len(years) >= 5 and eb == "strong":
            share = sum(1 for y in years if y >= 2025) / len(years)
            if share < 0.2:
                score = round(float(weights.get("temporal-gap", 1.5))
                              * (1 - share) * 0.5, 3)
                gaps.append({
                    "sub_direction": sub.get("name"),
                    "signal": "temporal-gap",
                    "hits": len(years),
                    "eligible": len(members_all),
                    "rate": round(share, 3),
                    "baseline": None,
                    "lift": None,
                    "score": score,
                    "opportunity": _opportunity(score, opp_high, opp_med),
                    "reason": (f"{sub.get('name')} 近两年文献占比仅 {share:.0%}"
                               f"（{sum(1 for y in years if y >= 2025)}/{len(years)}），"
                               f"而其概念页 evidence_base=strong；{SIGNAL_DESC['temporal-gap']}"),
                    "evidence_refs": _refs(members_all, cards),
                })
        # 跨域未迁移（子方向级）：邻域成熟但本方向未采用的技术
        if cd.get(sub.get("name")):
            cand, mature = cd[sub.get("name")]
            if len(cand) >= min_hits and mature:
                rate = len(cand) / len(mature)
                lift = round(rate - cd_base, 3)
                if lift >= min_lift:
                    score = round(float(weights.get("cross-domain-gap", 1.0)) * lift
                                  * (len(cand) / (len(cand) + 3.0)), 3)
                    shown = "、".join(cand[:6])
                    gaps.append({
                        "sub_direction": sub.get("name"),
                        "signal": "cross-domain-gap",
                        "hits": len(cand),
                        "eligible": len(mature),
                        "rate": round(rate, 3),
                        "baseline": cd_base,
                        "lift": lift,
                        "score": score,
                        "opportunity": _opportunity(score, opp_high, opp_med),
                        "reason": (f"{sub.get('name')} 的邻近子方向已成熟使用 {len(mature)} 项技术，"
                                   f"本方向有 {len(cand)} 项未采用（{shown}）；"
                                   f"全方向平均未采用率 {cd_base:.0%}（lift {lift:+.0%}）；"
                                   f"{SIGNAL_DESC['cross-domain-gap']}"),
                        "evidence_refs": _tech_refs(cand, sub.get("name"), subs, cards),
                    })
        # 方法证据薄（N3）：本方向仅 1 篇、邻域 ≥2 篇验证的方法
        if thin_stats.get(sub.get("name")):
            thin, n_used = thin_stats[sub.get("name")]
            if len(thin) >= min_hits and n_used:
                rate = len(thin) / n_used
                lift = round(rate - thin_base, 3)
                if lift >= min_lift:
                    score = round(float(weights.get("method-orphan", 1.0)) * lift
                                  * (len(thin) / (len(thin) + 3.0)), 3)
                    gaps.append({
                        "sub_direction": sub.get("name"),
                        "signal": "method-orphan",
                        "hits": len(thin),
                        "eligible": n_used,
                        "rate": round(rate, 3),
                        "baseline": thin_base,
                        "lift": lift,
                        "score": score,
                        "opportunity": _opportunity(score, opp_high, opp_med),
                        "reason": (f"{sub.get('name')} 的 {n_used} 个方法里，有 {len(thin)} 个"
                                   f"在本方向只有 1 篇支撑、邻域却有 ≥2 篇（如 "
                                   + "、".join(k.split('|')[0] for k in thin[:5])
                                   + f"）；全方向平均 {thin_base:.0%}（lift {lift:+.0%}）；"
                                   f"{SIGNAL_DESC['method-orphan']}"),
                        "evidence_refs": _key_refs(thin, sub.get("name"), subs, cards,
                                                   method_map),
                    })
    gaps.sort(key=lambda g: (-g["score"], g["sub_direction"], g["signal"]))
    by_signal = {}
    for g in gaps:
        by_signal[g["signal"]] = by_signal.get(g["signal"], 0) + 1
    by_sub = {}
    for g in gaps:
        by_sub[g["sub_direction"]] = max(by_sub.get(g["sub_direction"], 0), g["score"])
    summary = {
        "gaps": len(gaps),
        "by_signal": by_signal,
        "by_sub_direction": dict(sorted(by_sub.items(), key=lambda kv: -kv[1])),
        "high_opportunity": sum(1 for g in gaps if g["opportunity"] == "high"),
    }
    return gaps, summary


# ---------------------------------------------------------------- 组装 / 输出

def build(topic, cfg=None, min_hits=None, min_lift=None):
    cfg = cfg or load_config()
    gcfg = cfg.get("gapscan") or {}
    weights = {k: float((v or {}).get("weight") or 1.0)
               for k, v in (gcfg.get("signals") or {}).items()}
    min_hits = int(min_hits if min_hits is not None else gcfg.get("min_hits", 2))
    min_lift = float(min_lift if min_lift is not None else gcfg.get("min_lift", 0.1))

    lp = landscape_path(topic)
    land = load_landscape(lp)
    method_map = load_method_map(cfg)
    cards = read_cards(land.get("candidates") or [], method_map)
    subs = land.get("sub_directions") or []
    if not subs:
        raise SystemExit("[!] landscape.json 里没有 sub_directions；"
                         "先跑 sci_landscape.py --direction ... --cluster")

    base = baselines(cards)
    eb = load_evidence_bases()
    tech_usage = build_tech_usage(cards, subs)
    method_usage = build_method_usage(cards, subs, method_map)
    sigcfg = gcfg.get("signals") or {}
    gaps, summary = aggregate_gaps(cards, subs, base, eb, weights,
                                   min_hits=min_hits, min_lift=min_lift,
                                   opp_high=float(gcfg.get("opportunity_high",
                                                           OPPORTUNITY_HIGH)),
                                   opp_med=float(gcfg.get("opportunity_medium",
                                                          OPPORTUNITY_MED)),
                                   tech_usage=tech_usage,
                                   method_usage=method_usage,
                                   method_map=method_map,
                                   cd_min_cards=int((sigcfg.get("cross-domain-gap") or {})
                                                    .get("min_cards_per_other_sub", 3)),
                                   cd_min_subs=int((sigcfg.get("cross-domain-gap") or {})
                                                   .get("min_other_subs", 2)),
                                   orphan_min_other=int((sigcfg.get("method-orphan") or {})
                                                        .get("min_other_cards", 2)))

    missing = [n for n, c in cards.items() if c.get("missing")]
    data = {
        "topic_id": land.get("topic_id"),
        "query_direction": land.get("query_direction"),
        "generated_at": datetime.date.today().isoformat(),
        "source_landscape": os.path.relpath(lp, K.VAULT).replace("\\", "/"),
        "config": {
            "min_hits": min_hits,
            "min_lift": min_lift,
            "weights": weights,
            "baseline_rates": base,
            "note": ("判据 = 子方向命中率 − 全方向基线（lift），并要求命中数 ≥ min_hits。"
                     "标记普遍 ≠ 缺口：自报数字/单源论断在库内是常态。"
                     "⚠️ 信号依赖卡片上的批判性标记（ingest 时人工/AI 标注），"
                     "跨批次可能存在标注风格差异——gaps 是线索，不是定论。"),
        },
        "definitions": {s: SIGNAL_DESC[s] for s in
                        ("comp-no-expt", "synth-no-char", "single-lab-claim", "temporal-gap",
                         "method-orphan", "cross-domain-gap")},
        "gaps": gaps,
        "summary": summary,
        "coverage": {
            "candidates": len(cards),
            "cards_read": len(cards) - len(missing),
            "missing_files": missing,
            "sub_directions": len(subs),
            "review_cards": sum(1 for c in cards.values() if c.get("review")),
            "cards_with_method_records": sum(1 for c in cards.values()
                                             if c.get("has_record")),
            "method_keys_tracked": len(method_usage),
            "methods_db_loaded": method_map is not None,
            "techniques_tracked": len(tech_usage),
        },
    }
    return data


def out_path(topic, landscape_file=None):
    if landscape_file and landscape_file.endswith(".json"):
        return os.path.join(os.path.dirname(landscape_file), "gaps.json")
    return os.path.join(K.VAULT, "projects/sci-assistant/topics", topic, "gaps.json")


def write_json(path, data):
    text = json.dumps(data, ensure_ascii=False, indent=2)
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(text + "\n")
    with open(path, "r", encoding="utf-8") as f:
        back = json.load(f)
    if len(back.get("gaps") or []) != len(data.get("gaps") or []):
        raise SystemExit(f"[!] 写盘复算失败: {path}")
    return path


# ---------------------------------------------------------------- 自检

def _selftest():
    fails = []

    def chk(label, cond, detail=""):
        print(("  ok   " if cond else "  FAIL ") + label +
              (f"   [{detail}]" if detail and not cond else ""))
        if not cond:
            fails.append(label)

    # 1) 单卡信号
    sig, d = detect_card_signals("> ⚠️ 无实验验证：稳定性均由 PBE 判定，未做合成")
    chk("信号：无实验验证标记 -> comp-no-expt", "comp-no-expt" in sig)
    sig, d = detect_card_signals("正文用 VASP 做 DFT 计算，未涉及任何合成。")
    chk("信号：没有标记时不靠结构启发式报 comp-no-expt（v0 只用标记）",
        "comp-no-expt" not in sig)
    sig, d = detect_card_signals("采用水热合成制备样品，仅做了 XRD。")
    chk("信号：合成 + 仅 1 种表征 -> synth-no-char", "synth-no-char" in sig)
    sig, d = detect_card_signals("采用水热合成制备样品，并做了 SEM、XRD、XPS、EIS 表征。")
    chk("信号：表征充足 -> 不报 synth-no-char", "synth-no-char" not in sig)
    sig, d = detect_card_signals("> ⚠️ 体裁提示：本文为综述\n水热合成……仅 XRD。")
    chk("信号：综述不计 synth-no-char", "synth-no-char" not in sig and d["review"])
    sig, d = detect_card_signals("> ⚠️ 自报数字：库仑效率 99.9%\n> ⚠️ 单源论断：仅本组报道")
    chk("信号：双标记 -> single-lab-claim", "single-lab-claim" in sig)
    sig, d = detect_card_signals("> ⚠️ 自报数字：库仑效率 99.9%")
    chk("信号：仅自报数字不报 single-lab-claim（库内常态）", "single-lab-claim" not in sig)

    # 2) 聚合：lift 判定 + min_hits + 机会分级
    cards = {}
    # 子方向 A：6 篇里 5 篇 comp-no-expt（高 lift）；B：6 篇里 1 篇（低 lift，应过滤）
    for i in range(6):
        cards[f"a{i}"] = {"signals": {"comp-no-expt"} if i < 5 else set(),
                          "year": "2026", "score": 1.0, "review": False, "missing": False}
    for i in range(6):
        cards[f"b{i}"] = {"signals": {"comp-no-expt"} if i < 1 else set(),
                          "year": "2026", "score": 1.0, "review": False, "missing": False}
    subs = [{"name": "A", "members": [f"a{i}" for i in range(6)]},
            {"name": "B", "members": [f"b{i}" for i in range(6)]}]
    base = {"comp-no-expt": 0.5}
    gaps, summ = aggregate_gaps(cards, subs, base, {"A": "strong"},
                                {"comp-no-expt": 3.0}, min_hits=2, min_lift=0.1)
    names = [g["sub_direction"] for g in gaps]
    chk("聚合：高 lift 子方向被报出、低 lift 被过滤",
        "A" in names and "B" not in names)
    gapA = [g for g in gaps if g["sub_direction"] == "A"][0]
    chk("聚合：lift = 命中率 − 基线",
        abs(gapA["lift"] - round(5 / 6 - 0.5, 3)) < 1e-9)
    chk("聚合：机会分级 high/medium/low 取值合法",
        all(g["opportunity"] in ("high", "medium", "low") for g in gaps))
    gaps2, _ = aggregate_gaps(cards, subs, base, {}, {"comp-no-expt": 3.0},
                              min_hits=10, min_lift=0.1)
    chk("聚合：min_hits 过滤生效", gaps2 == [])

    # 3) 时间空白：evidence_base=strong + 近两年占比低
    old = {f"c{i}": {"signals": set(), "year": "2020", "score": 1.0,
                     "review": False, "missing": False} for i in range(6)}
    gaps3, _ = aggregate_gaps(old, [{"name": "C", "members": list(old)}],
                              {}, {"C": "strong"}, {"temporal-gap": 1.5},
                              min_hits=2, min_lift=0.1)
    chk("聚合：旧文献 + strong 证据 -> temporal-gap",
        any(g["signal"] == "temporal-gap" for g in gaps3))
    gaps4, _ = aggregate_gaps(old, [{"name": "C", "members": list(old)}],
                              {}, {"C": "mixed"}, {"temporal-gap": 1.5},
                              min_hits=2, min_lift=0.1)
    chk("聚合：证据不 strong 时不报 temporal-gap", gaps4 == [])

    # 4) 基线：综述不计入 synth 信号分母
    cs = {
        "r1": {"signals": {"synth-no-char", "comp-no-expt"}, "review": True,
               "missing": False, "year": "2026"},
        "p1": {"signals": set(), "review": False, "missing": False, "year": "2026"},
        "p2": {"signals": set(), "review": False, "missing": False, "year": "2026"},
    }
    b = baselines(cs)
    chk("基线：综述被排除在卡级信号分母外",
        b["synth-no-char"] == 0.0 and b["comp-no-expt"] == 0.0)

    # 5) N3：方法证据薄（本方向 1 篇、邻域 ≥2 篇）
    mm = {"per_card": {"a1": {"Raman|表征"}, "a2": {"XRD|表征"},
                       "b1": {"Raman|表征"}, "b2": {"Raman|表征"},
                       "c1": {"Raman|表征"}, "c2": {"Raman|表征"}},
          "key_cards": {}}
    cards_m = {k: {"techniques": [], "signals": set(), "review": False, "missing": False,
                   "year": "2026", "score": 1.0, "has_record": True} for k in mm["per_card"]}
    subs_m = [{"name": "A", "members": ["a1", "a2"]},
              {"name": "B", "members": ["b1", "b2"]},
              {"name": "C", "members": ["c1", "c2"]}]
    usage_m = build_method_usage(cards_m, subs_m, mm)
    thinA, usedA = thin_methods_for("A", usage_m)
    chk("薄证据：A 的 Raman 只 1 篇、邻域 4 篇 -> thin",
        thinA == ["Raman|表征"] and len(usedA) == 2, str(thinA))
    chk("薄证据：B/C 的 Raman 各 2 篇 -> 不算 thin",
        thin_methods_for("B", usage_m)[0] == [])
    gaps_m, _ = aggregate_gaps(cards_m, subs_m, {}, {}, {"method-orphan": 1.0},
                               min_hits=1, min_lift=0.05,
                               method_usage=usage_m, method_map=mm)
    gm = next((g for g in gaps_m if g["sub_direction"] == "A"
               and g["signal"] == "method-orphan"), None)
    chk("薄证据：A 报 method-orphan 且 hits=1/eligible=2",
        gm is not None and gm["hits"] == 1 and gm["eligible"] == 2, str(gaps_m))

    # 6) N3：跨域未迁移（子方向级）
    usage = {"T1": {"A": 3, "B": 3, "C": 3, "D": 3},
             "T2": {"A": 3, "B": 3, "C": 3, "D": 3},
             "T3": {"A": 3, "B": 3, "C": 3, "D": 3},
             "T4": {"A": 0, "B": 3, "C": 3, "D": 3},
             "T5": {"A": 0, "B": 3, "C": 3, "D": 3}}
    candA, matureA = cross_domain_for("A", {}, [], usage)
    chk("跨域：邻域成熟但本方向未采用 -> 候选 T4/T5",
        set(candA) == {"T4", "T5"} and set(matureA) == {"T1", "T2", "T3", "T4", "T5"},
        str(candA))
    chk("跨域：本方向已用 -> 不进候选", "T1" not in candA)
    candB, _ = cross_domain_for("B", {}, [], usage)
    chk("跨域：邻域技术已被本方向采用 -> 候选为空", candB == [])

    cards_cd, subs_cd = {}, []
    for sub, techs in (("A", ["T1", "T2", "T3"]), ("B", ["T1", "T2", "T3", "T4", "T5"]),
                       ("C", ["T1", "T2", "T3", "T4", "T5"]),
                       ("D", ["T1", "T2", "T3", "T4", "T5"])):
        members = []
        for k in range(3):
            name = f"{sub}{k}"
            cards_cd[name] = {"signals": set(), "techniques": techs, "year": "2026",
                              "score": 1.0, "review": False, "missing": False,
                              "has_record": False, "method_orphan": False}
            members.append(name)
        subs_cd.append({"name": sub, "members": members})
    tu = build_tech_usage(cards_cd, subs_cd)
    gaps_cd, _ = aggregate_gaps(cards_cd, subs_cd, {}, {}, {"cross-domain-gap": 1.0},
                                min_hits=2, min_lift=0.05, tech_usage=tu)
    ga = next((g for g in gaps_cd if g["sub_direction"] == "A"
               and g["signal"] == "cross-domain-gap"), None)
    chk("跨域：A 缺 T4/T5 -> 报 cross-domain-gap 且 hits=2",
        ga is not None and ga["hits"] == 2 and ga["eligible"] == 5, str(ga))
    chk("跨域：B/C/D 不缺技术 -> 不报",
        not any(g["sub_direction"] != "A" and g["signal"] == "cross-domain-gap"
                for g in gaps_cd))

    # 5) 零样本不崩
    g, s = aggregate_gaps({}, [], {}, {}, {})
    chk("聚合：空输入不崩", g == [] and s["gaps"] == 0)

    print(f"SELFTEST {'PASSED' if not fails else 'FAILED'}: {len(fails)} failure(s)")
    return 0 if not fails else 1


# ---------------------------------------------------------------- CLI

def main(argv=None):
    ap = argparse.ArgumentParser(description="科学内容空白识别（Phase 1b）")
    ap.add_argument("--topic", help="方向名或 landscape.json 路径")
    ap.add_argument("--out", default=None, help="输出路径（默认同目录 gaps.json）")
    ap.add_argument("--json", action="store_true", help="结果 JSON 打印到 stdout")
    ap.add_argument("--no-write", action="store_true", help="不写盘")
    ap.add_argument("--min-hits", type=int, default=None, help="覆盖配置里的最小命中数")
    ap.add_argument("--min-lift", type=float, default=None, help="覆盖配置里的最小 lift")
    ap.add_argument("--selftest", action="store_true", help="自检（不依赖知识库）")
    args = ap.parse_args(argv)

    if args.selftest:
        return _selftest()
    if not args.topic:
        ap.print_help()
        return 1

    data = build(args.topic, min_hits=args.min_hits, min_lift=args.min_lift)
    if args.json:
        print(json.dumps(data, ensure_ascii=False, indent=2))
    if not args.no_write:
        p = args.out or out_path(args.topic, landscape_path(args.topic)
                                 if args.topic.endswith(".json") else None)
        p = write_json(p, data)
        s = data["summary"]
        print(f"[ok] {data['query_direction']}：{s['gaps']} 个空白，"
              f"{s['high_opportunity']} 个高机会")
        for sig, n in sorted(s["by_signal"].items(), key=lambda kv: -kv[1]):
            print(f"     - {sig}: {n}")
        print(f"     输出: {os.path.relpath(p, K.VAULT)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
